function timedItems(items,id){
 const rows=Array.isArray(items)?items:[];
 if(!rows.length)return `<p class="quiet">${t('noData')}</p>`;
 return rows.map(item=>{
  const seconds=Number(item.start??item.playback_time),hasTime=item.start!=null||item.playback_time!=null;
  const label=item.title||item.text||item.excerpt||item.summary||t('unknown');
  const detail=item.title?(item.summary||item.excerpt||''):'';
  const content=`<span>${esc(label)}${detail?`<small class="quiet">${esc(detail)}</small>`:''}</span><strong class="mono">${hasTime&&Number.isFinite(seconds)?esc(item.start_display||fmtTime(seconds)):'—'}</strong>`;
  return hasTime&&Number.isFinite(seconds)?`<a class="setting" href="${idLink(id)}?t=${encodeURIComponent(seconds)}">${content}</a>`:`<div class="setting">${content}</div>`;
 }).join('')
}
function renderSpeakerInsights(data,id){const acoustic=data.speakers?.acoustic_diarization||{},ar=language==='ar',rows=acoustic.speakers||[];return `<h4>${ar?'مشاركة الأصوات':'Acoustic participation'}</h4>${pill(acoustic.status||t('unknown'))}${rows.length?rows.map(s=>`<details><summary class="setting"><span>${esc(s.speaker_id)} ${s.username?'· @'+esc(s.username):''}</span><strong class="mono">${fmtTime(s.total_speaking_seconds)} · ${Number(s.turn_count||0)}</strong></summary><div class="quiet">${ar?'عدد المداخلات والمدد من الفصل الصوتي؛ هوية الحساب تتطلب دليلًا منفصلًا.':'Turns and durations come from acoustic separation; account identity requires separate evidence.'}</div>${(s.turns||[]).slice(0,10).map(x=>`<a class="setting" href="${idLink(id)}?t=${Number(x.start)||0}"><span class="mono">${fmtTime(x.start)} → ${fmtTime(x.end)}</span><strong>${Number(x.speech_seconds||0).toFixed(1)}s</strong></a>`).join('')}${timedItems(s.text_summary?.excerpts||[],id)}</details>`).join(''):`<p class="quiet">${ar?'لا توجد نتيجة صوتية متحققة من مصادر التسجيل الحالية.':'No acoustic result verified against the current recording sources.'}</p>`}`}
